159	+   Ảnh là đúng khung WebGL vừa vẽ: stPhotoAfterRender chạy ngay sau lệnh vẽ chính trong animate (cùng tác vụ) nên toBlob đọc được bộ đệm vừa vẽ,
160	+   không cần preserveDrawingBuffer. Nhãn tên và mọi phần tử HTML (kể cả chớp trắng) không có trong ảnh.
161	+   Bấm nhiều lần trước khi khung kế tiếp vẽ chỉ xếp một yêu cầu. Kích thước ảnh lấy tại lúc chụp (canvas.width / height), không đọc lại sau.
162	+   Điện thoại (hover: none) có canShare thì mở bảng chia sẻ; còn lại tải file qua <a download>. Hủy bảng chia sẻ (AbortError) không phải lỗi.
163	+   Khi không có yêu cầu chờ, mỗi khung chỉ một phép so sánh, không cấp phát. */
164	+import { CONFIG } from '../../config';
165	+import { t } from '../../i18n';
166	+import { exWatchNotice } from '../multi/watch';
167	+
168	+let pending = false;   // có một yêu cầu chụp chờ khung kế tiếp
169	+export let stPhotoLast: { name: string; size: number; w: number; h: number } | null = null;   // ảnh vừa chụp (cho test)
170	+
171	+const pad = (n: number): string => (n < 10 ? '0' : '') + n;
172	+
173	+/* danang-YYYYMMDD-HHMMSS.png theo giờ máy người dùng */
174	+export function stPhotoName(d: Date): string {
175	+  return `danang-${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}.png`;
176	+}
177	+
178	+/* Thông báo ngắn ở #exMpNotice (cùng chỗ với các thông báo đi dạo khác), tự ẩn sau noticeMs nếu chưa bị thay */
179	+function notice(key: string): void {
180	+  exWatchNotice(key);
181	+  const text = t(key);
182	+  window.setTimeout(() => { const el = document.getElementById('exMpNotice'); if (el && el.textContent === text) exWatchNotice(''); }, CONFIG.explore.multi.noticeMs);
183	+}
184	+
185	+export function stPhotoRequest(): void { pending = true; }
186	+
187	+/* Lưu: chia sẻ trên điện thoại, còn lại tải về */
188	+function save(blob: Blob, name: string): void {
189	+  const file = new File([blob], name, { type: 'image/png' });
190	+  const nav = navigator as Navigator & { canShare?: (d: ShareData) => boolean };
191	+  if (window.matchMedia('(hover: none)').matches && nav.canShare && nav.canShare({ files: [file] })) {
192	+    navigator.share({ files: [file] }).then(() => notice('stPhotoSaved'), (e: unknown) => { if ((e as { name?: string }).name !== 'AbortError') notice('stPhotoFail'); });
193	+    return;
194	+  }
195	+  const url = URL.createObjectURL(blob), a = document.createElement('a');
196	+  a.href = url; a.download = name; a.style.display = 'none';
197	+  document.body.appendChild(a); a.click(); a.remove();
198	+  window.setTimeout(() => URL.revokeObjectURL(url), CONFIG.stroll.photoUrlMs);
199	+  notice('stPhotoSaved');
200	+}
201	+
202	+/* Gọi ngay sau lệnh vẽ khung chính: nếu có yêu cầu thì chụp canvas */
203	+export function stPhotoAfterRender(canvas: HTMLCanvasElement): void {
204	+  if (!pending) return;
205	+  pending = false;
206	+  const w = canvas.width, h = canvas.height, name = stPhotoName(new Date());
207	+  try {
208	+    canvas.toBlob((blob) => {
209	+      if (!blob || blob.size === 0) { notice('stPhotoFail'); return; }
210	+      stPhotoLast = { name, size: blob.size, w, h };
211	+      save(blob, name);
212	+    }, 'image/png');
213	+  } catch { notice('stPhotoFail'); }
214	+}
